#!/usr/bin/env python3
"""Regenerate deterministic ground truth for CSX-298_Q2."""

from __future__ import annotations

import json
import warnings
from collections.abc import Iterable
from pathlib import Path
from typing import Iterator

from PIL import Image


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-298"
OUTPUT_PATH = TASK_DIR / "computed_gt.json"

TARGET_FAMILY = "godzilla_2020_truecolor_dust_veil_surface_rainfall_index"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_June_2020_Saharan_dust_Godzilla_outbreak.json",
    "data/remote_sensing/remote_sensing_008_pre_2020-05-15_modis_truecolor.jpg.jpg",
    "data/remote_sensing/remote_sensing_007_event_2020-06-21_modis_truecolor.jpg.jpg",
    "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json",
    "data/physical_hazard/physical_hazard_001_NASA_POWER_daily_point_sample.json",
    "data/physical_hazard/physical_hazard_002_Open-Meteo_archive_point_sample.json",
]


def read_json(rel_path: str) -> dict:
    with (PACKAGE_DIR / rel_path).open("r", encoding="utf-8-sig") as handle:
        return json.load(handle)


def iter_rgb_pixels(pixel_source: Iterable[object]) -> Iterator[tuple[int, int, int]]:
    """Yield RGB triples from tuple/list pixels or a flat numeric RGB stream."""
    iterator = iter(pixel_source)
    flat_prefix: list[object] = []

    for item in iterator:
        if isinstance(item, (tuple, list)):
            if len(item) < 3:
                raise ValueError("RGB pixel entries must contain at least three channels")
            yield int(item[0]), int(item[1]), int(item[2])
            continue
        flat_prefix.append(item)
        break

    if not flat_prefix:
        return

    flat_values = flat_prefix + list(iterator)
    if len(flat_values) % 3 != 0:
        raise ValueError("Flat RGB pixel stream length must be divisible by three")

    for index in range(0, len(flat_values), 3):
        yield int(flat_values[index]), int(flat_values[index + 1]), int(flat_values[index + 2])


def image_stats(rel_path: str) -> dict:
    image = Image.open(PACKAGE_DIR / rel_path).convert("RGB")
    if hasattr(image, "get_flattened_data"):
        pixel_source = image.get_flattened_data()
    else:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", DeprecationWarning)
            pixel_source = image.getdata()

    total = 0
    red_sum = 0
    green_sum = 0
    blue_sum = 0
    blue_water = 0
    tan_dust = 0

    for red, green, blue in iter_rgb_pixels(pixel_source):
        total += 1
        red_sum += red
        green_sum += green
        blue_sum += blue

        if blue > red + 15 and blue > green + 5 and blue > 80:
            blue_water += 1
        if red > green > blue and red >= 95 and green >= 85 and red - blue >= 15 and green - blue >= 5:
            tan_dust += 1

    brightness = (red_sum + green_sum + blue_sum) / (3.0 * total)
    return {
        "width": image.width,
        "height": image.height,
        "brightness": round(brightness, 4),
        "blue_water_fraction": round(blue_water / total, 6),
        "tan_dust_fraction": round(tan_dust / total, 6),
    }


def round2(value: float) -> float:
    return round(float(value), 2)


def precipitation_total_power(power: dict) -> float:
    return sum(float(value) for value in power["properties"]["parameter"]["PRECTOTCORR"].values())


def precipitation_total_open_meteo(open_meteo: dict) -> float:
    return sum(float(value) for value in open_meteo["daily"]["precipitation_sum"])


def build_result() -> dict:
    event = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_June_2020_Saharan_dust_Godzilla_outbreak.json"
    )
    surface_change = read_json(
        "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json"
    )
    power = read_json("data/physical_hazard/physical_hazard_001_NASA_POWER_daily_point_sample.json")
    open_meteo = read_json("data/physical_hazard/physical_hazard_002_Open-Meteo_archive_point_sample.json")

    pre = image_stats("data/remote_sensing/remote_sensing_008_pre_2020-05-15_modis_truecolor.jpg.jpg")
    event_img = image_stats("data/remote_sensing/remote_sensing_007_event_2020-06-21_modis_truecolor.jpg.jpg")

    brightness_delta = event_img["brightness"] - pre["brightness"]
    blue_water_drop_pp = 100.0 * (pre["blue_water_fraction"] - event_img["blue_water_fraction"])
    tan_dust_gain_pp = 100.0 * (event_img["tan_dust_fraction"] - pre["tan_dust_fraction"])
    dust_veil_index = brightness_delta / 10.0 + blue_water_drop_pp / 4.0 + tan_dust_gain_pp / 2.0

    surface_mean = float(surface_change["stats"]["alphaearth_1_minus_cosine_mean"])
    surface_stddev = float(surface_change["stats"]["alphaearth_1_minus_cosine_stdDev"])
    surface_change_ratio = max(surface_mean, surface_stddev) / 0.02

    power_precip_total_mm = precipitation_total_power(power)
    open_meteo_precip_total_mm = precipitation_total_open_meteo(open_meteo)
    point_rainfall_max_mm = max(power_precip_total_mm, open_meteo_precip_total_mm)

    answer = {
        "brightness_delta": round2(brightness_delta),
        "blue_water_drop_pp": round2(blue_water_drop_pp),
        "tan_dust_gain_pp": round2(tan_dust_gain_pp),
        "dust_veil_index": round2(dust_veil_index),
        "surface_change_ratio": round2(surface_change_ratio),
        "point_rainfall_max_mm": round2(point_rainfall_max_mm),
        "pass_count": 0,
        "conclusion": "dust_veil_not_surface_or_rainfall",
    }

    gates = {
        "brightness_delta_ge_8": answer["brightness_delta"] >= 8.0,
        "blue_water_drop_pp_ge_4": answer["blue_water_drop_pp"] >= 4.0,
        "tan_dust_gain_pp_ge_2": answer["tan_dust_gain_pp"] >= 2.0,
        "dust_veil_index_ge_4": answer["dust_veil_index"] >= 4.0,
        "surface_change_ratio_lt_1": answer["surface_change_ratio"] < 1.0,
        "point_rainfall_max_mm_lt_5": answer["point_rainfall_max_mm"] < 5.0,
    }
    answer["pass_count"] = sum(1 for passed in gates.values() if passed)

    thresholds = {
        "brightness_delta_min": 8,
        "blue_water_drop_pp_min": 4,
        "tan_dust_gain_pp_min": 2,
        "dust_veil_index_min": 4,
        "surface_change_ratio_max": 1,
        "point_rainfall_max_mm_max": 5,
    }

    return {
        "schema_version": "1.0",
        "task_id": "CSX-298_Q2",
        "event_id": "CSX-298",
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "target_family": TARGET_FAMILY,
        "primary_gt": {
            "answer": "dust_veil_not_surface_or_rainfall",
            **answer,
            "expected_json": answer,
            "thresholds": thresholds,
            "tolerances": {
                "image_delta_or_rainfall": 0.05,
                "index_or_ratio": 0.02,
                "pass_count": 0,
            },
            "label": "godzilla_2020_dust_veil_pass",
        },
        "event": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_window": {
                "start": anchor["temporal_window"]["start_date"],
                "end": anchor["temporal_window"]["end_date"],
            },
            "region": "Sahara, Atlantic, and Caribbean",
        },
        "key_values": {
            "pre_image": pre,
            "event_image": event_img,
            "unrounded": {
                "brightness_delta": brightness_delta,
                "blue_water_drop_pp": blue_water_drop_pp,
                "tan_dust_gain_pp": tan_dust_gain_pp,
                "dust_veil_index": dust_veil_index,
                "surface_change_ratio": surface_change_ratio,
                "power_precip_total_mm": power_precip_total_mm,
                "open_meteo_precip_total_mm": open_meteo_precip_total_mm,
            },
            "surface_change": {
                "mean": surface_mean,
                "stddev": surface_stddev,
                "cutoff": 0.02,
            },
            "gates": gates,
            "formulas": {
                "brightness": "mean((R+G+B)/3)",
                "blue_water_fraction": "count(B>R+15 and B>G+5 and B>80)/pixels",
                "tan_dust_fraction": "count(R>G>B and R>=95 and G>=85 and R-B>=15 and G-B>=5)/pixels",
                "dust_veil_index": "brightness_delta/10 + blue_water_drop_pp/4 + tan_dust_gain_pp/2",
                "surface_change_ratio": "max(surface_mean,surface_stddev)/0.02",
                "point_rainfall_max_mm": "max(POWER_total,Open-Meteo_total)",
            },
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Answer schema",
                    "points": 3,
                    "description": "Returns the requested JSON fields with numeric values, an integer pass count, and the expected conclusion label.",
                    "partial_credit": "Award 1-2 points for recoverable values with minor field-name or rounding mistakes.",
                },
                {
                    "name": "Image statistics",
                    "points": 5,
                    "description": "Computes RGB brightness, blue-water fraction, tan-dust fraction over all RGB pixels in each package scene as delivered, and the three event-minus-pre-event deltas with correct units.",
                    "partial_credit": "Award partial credit for correct formulas with one image class or percentage-point arithmetic error.",
                },
                {
                    "name": "Dust-veil index",
                    "points": 4,
                    "description": "Applies the stated dust-veil index formula and reports 4.49 with the correct threshold pass state.",
                    "partial_credit": "Award 2 points for the correct formula with one arithmetic or rounding error.",
                },
                {
                    "name": "Confounder gates",
                    "points": 4,
                    "description": "Computes surface_change_ratio near 0.41 and point_rainfall_max_mm near 2.37, then applies both gates correctly.",
                    "partial_credit": "Award 2 points if only one of the two confounder gates is correct.",
                },
                {
                    "name": "Gate count and label",
                    "points": 3,
                    "description": "Reports six passing gates and the label dust_veil_not_surface_or_rainfall.",
                    "partial_credit": "Award 1-2 points for a correct pass count with an imprecise but consistent label, or the reverse.",
                },
                {
                    "name": "Scope control",
                    "points": 1,
                    "description": "Keeps the interpretation to the computed consequence and does not add durable-damage, loss, or rainfall-causation statements.",
                    "partial_credit": "Award 0.5 points for a correct numeric result with a minor harmless overstatement.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "All numeric anchors are regenerated from local CSX-298 package files.",
        },
        "supporting_metrics": {
            "image_method": {
                "pixel_scope": "all RGB pixels in each package true-color scene as delivered",
                "no_data_handling": "no separate no-data mask is applied",
            },
            "confounder_scope": {
                "surface_change_ratio": "durable-surface-change confounder gate only",
                "point_rainfall_max_mm": "package point-rainfall confounder gate only",
            },
        },
    }


def main() -> None:
    OUTPUT_PATH.write_text(json.dumps(build_result(), indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
